// UUID v4 Generator

var count = parseInt(input.get("count") || "1");
var format = input.get("format") || "lowercase";
var separator = input.get("separator") || "newline";

function generateUuid() {
    // UUID v4 format: xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx
    // where x is any hex digit and y is 8, 9, A, or B
    var hex = '0123456789abcdef';
    var uuid = '';

    for (var i = 0; i < 36; i++) {
        if (i === 8 || i === 13 || i === 18 || i === 23) {
            uuid += '-';
        } else if (i === 14) {
            uuid += '4'; // Version 4
        } else if (i === 19) {
            // Variant bits: 8, 9, a, or b
            uuid += hex[(Math.random() * 4 | 0) + 8];
        } else {
            uuid += hex[Math.random() * 16 | 0];
        }
    }

    return uuid;
}

try {
    if (count < 1) count = 1;
    if (count > 1000) count = 1000; // Limit to prevent abuse

    var uuids = [];
    for (var i = 0; i < count; i++) {
        var uuid = generateUuid();
        if (format === "uppercase") {
            uuid = uuid.toUpperCase();
        } else if (format === "no-hyphens") {
            uuid = uuid.replace(/-/g, '');
        } else if (format === "braces") {
            uuid = '{' + uuid + '}';
        } else if (format === "urn") {
            uuid = 'urn:uuid:' + uuid;
        }
        uuids.push(uuid);
    }

    var sep = '\n';
    if (separator === "comma") sep = ',';
    else if (separator === "semicolon") sep = ';';
    else if (separator === "space") sep = ' ';
    else if (separator === "pipe") sep = '|';

    var result = uuids.join(sep);

    output.set("Uuid", uuids[0]); // First UUID for single-use
    output.set("Uuids", result); // All UUIDs
    output.set("UuidArray", json.stringify(uuids)); // As JSON array
    output.set("Count", uuids.length);
    output.set("Format", format);
    output.set("HasErrors", false);
    output.set("ErrorMessage", "");

    log.info("Generated " + count + " UUID(s): " + uuids[0] + (count > 1 ? "..." : ""));
    tags.trigger("success");

} catch (ex) {
    log.error("UUID generation failed: " + ex.message);
    output.set("HasErrors", true);
    output.set("ErrorMessage", ex.message);
    output.set("Uuid", "");
    tags.trigger("error");
}
